function Editor() {
  const [text, setText] = useState("");
  const [count, setCount] = useState(0);

  useEffect(() => { setCount(text.length); }, []); // note the deps

  return (
    <>
      <input value={text} onChange={(e) => setText(e.target.value)} />
      <span>{count}</span>
    </>
  );
}

// The user types "hello".

function Editor({ description }) {
  const [text, setText] = useState(description);
  useEffect(() => { setText(description); }); // no dep array
  return <input value={text} onChange={(e) => setText(e.target.value)} />;
}

// description is "Draft". The user types "X" at the end.

function Widget() {
  const [resizes, setResizes] = useState(0);
  useEffect(() => {
    window.addEventListener("resize", () => setResizes((r) => r + 1));
  }); // no deps, no cleanup
  return <span>{resizes}</span>;
}

// The window is resized twice (one event each).
